bool BraveNewsController_GetLocale_ForwardToCallback::Accept(
    mojo::Message* message) {
  DCHECK(message->is_serialized());
  internal::BraveNewsController_GetLocale_ResponseParams_Data* params =
      reinterpret_cast<
          internal::BraveNewsController_GetLocale_ResponseParams_Data*>(
              message->mutable_payload());
  

  // Validation for BraveNewsController.0
  bool success = true;
  std::string p_locale{};
  BraveNewsController_GetLocale_ResponseParamsDataView input_data_view(params, message);
  
  if (success && !input_data_view.ReadLocale(&p_locale))
    success = false;
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        BraveNewsController::Name_, 0, true);
    return false;
  }
  if (!callback_.is_null()) {
    std::move(callback_).Run(
std::move(p_locale));
  }
  return true;
}

